 "content": "def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    # Each marked down-right diagonal encodes one position in the repeating
    # sequence of parallel diagonal bands.
    bands = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                d = c - r
                if d in bands and bands[d] != value:
                    raise ValueError("inconsistent colors on a diagonal")
                bands[d] = value
    if not bands:
        return [row[:] for row in grid]
    period = len(bands)
    colors = {d % period: color for d, color in bands.items()}
    # The examples provide one marked diagonal for each phase of the cycle.
    # Fill all parallel bands, repeating that cycle over the whole rectangle.
    return [[colors[(c - r) % period] for c in range(w)] for r in range(h)]
